                                        <h3 className="text-[11px] font-semibold text-[#8b6e5a] uppercase tracking-widest leading-tight mb-1.5 group-hover:text-[#10221c] transition-colors line-clamp-2">
                                            {product.name}
                                        </h3>
                                        <p className="text-sm font-medium text-gray-900">
                                            ₹{product.price?.toLocaleString('en-IN')}.00
                                        </p>
                                    </div>
                                </Link>
                            );
                        })}
                    </div>

                    {/* VIEW ALL Button */}
                    <div className="flex justify-center mt-12">
                        <Link
                            to="/shop"
                            className="px-10 py-3.5 bg-[#2d1a14] text-white text-xs font-semibold uppercase tracking-[0.2em] hover:bg-[#10221c] transition-colors"
                        >
